// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

var N_ANIM = 25; // how long the animation stage lasts
var N_WAIT = 25; // how long the wait stage lasts

var n = 10; // size of the grid (should be an odd multiple of the length of the palette)
var sections = [...Array(n)].map((e) => Array(n));
var weights1 = []; // weights of first compo
var weights2 = []; // weights of second compo

var imgWidth, imgHeight;
var wMargin, hMargin;
var phase = 0;

var img;

var myFont;
var loopCount = 0, nLoops = 5;
var weightsPerPhase = [];

function preload() {
	img = loadImage("file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/courbet.jpg");
	myFont = loadFont("file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/FragmentMono_Regular.ttf");
}

function setup() {
	createCanvas(500, 500);
	wMargin = 45;
	imgWidth = width-2*wMargin;
	imgHeight = img.height*imgWidth/img.width;
	hMargin = (height-imgHeight)/2;

	textAlign(CENTER, CENTER);
	textFont(myFont, 18);

	let w = img.width/n, h = img.height/n;
	for (let i = 0; i < n; i++) {
		let x = i*w;
		for (let j = 0; j < n; j++) {
			let y = j*h;
			sections[i][j] = img.get(x, y, w, h);
		}
	}

	for (let i = 0; i < n; i++) {
		weights1.push([1, 1]);
		weights2.push([1, 1]);
	}

	for (let i = 0; i < nLoops; i++) {
		let weights = [];
		for (let j = 0; j < n; j++) {
			weights.push(i >= nLoops-2 ? [1, 1] : [random(1, 10), random(1, 10)]);
		}
		weightsPerPhase.push(weights);
	}
}

function draw() {
	if (frameCount%(N_ANIM+N_WAIT) == 0) {
		if (loopCount == nLoops) {
			loopCount = 0;
			phase = (phase+1)%3;
		}
		for (let i = 0; i < n; i++) {
			weights1[i] = weights2[i];
			weights2[i] = weightsPerPhase[loopCount][i];
		}
		loopCount++;
	}

	background(255);

	let t, f = (frameCount)%(N_ANIM+N_WAIT);
	if (f < N_ANIM) t = easeInOutQuint((f%N_ANIM)/N_ANIM);
	else if (f < N_ANIM+N_WAIT) t = 1;

	let lerpedWeights = [];
	let wSum = 0, hSums = [];
	for (let i = 0; i < n; i++) {
		let weightsLine = [];

		var w = lerp(weights1[i][0], weights2[i][0], t);
		wSum += w;
		let hSum = 0;
		for (let j = 0; j < n; j++) {
			let h = lerp(weights1[j][1], weights2[j][1], t);
			hSum += h;
			weightsLine.push([w, h]);
		}
		hSums.push(hSum);
		lerpedWeights.push(weightsLine);
	}

	var x = wMargin;
	let uw = imgWidth/wSum;
	for (let i = 0; i < n; i++) {
		var y = hMargin;
		let uh = imgHeight/hSums[i];
		var w = lerpedWeights[i][0][0]*uw;
		for (let j = 0; j < n; j++) {
			var h = lerpedWeights[i][j][1]*uh;
			let section = sections[i][j];
			image(section, x, y, w+1, h+1);

			let sw = 1.5;
			if (phase == 0) {
				strokeWeight(sw);
				if (loopCount < nLoops) {
					fill(255);
				} else {
					fill(255, lerp(255, 0, t));
				}
				stroke(255, 0, 0);
			} else if (phase == 1) {
				noFill();
				if (loopCount < nLoops) {
					strokeWeight(sw);
				} else {
					strokeWeight(lerp(sw, 0, t));
				}
			} else {
				noFill();
				if (loopCount == nLoops) {
					fill(255, lerp(0, 255, t));
					strokeWeight(lerp(0, sw, t));
				}
			}
			stroke(255, 0, 0);
			rect(x, y, w+1, h+1);

			y += h;
		}
		x += w;
	}

	noStroke();
	fill(0);
	let instructions = ["Deform grid", "Stretch image accordingly", "Hide grid"];
	let str = (loopCount < nLoops) ? instructions[phase] : lerpText(instructions[phase], instructions[(phase+1)%3], t);
	text(str, width/2, height-hMargin/2-4);
}

function lerpText(str1, str2, t) {
	let start = "";
	let i = 0;
	let _wG_1 = 0; while ((str1[i] == str2[i] && i < str1.length && i < str2.length) && ++_wG_1 < 20000) {
		start = start + str1[i];
		i++;
	}
	let end = "";
	let j = 0;
	let _wG_2 = 0; while ((str1[str1.length-j-1] == str2[str2.length-j-1] && j < str1.length && j < str2.length) && ++_wG_2 < 20000) {
		end = str1[str1.length-j-1] + end;
		j++;
	}
	str1 = str1.slice(i, str1.length-j);
	str2 = str2.slice(i, str2.length-j);

	let middle = "";
	let idx1 = ~~lerp(0, str2.length, t);
	for (let i = 0; i < idx1; i++) {
		middle += str2[i];
	}
	let idx2 = ~~lerp(0, max(0, str1.length-str2.length), t);
	for (let i = idx1; i < str1.length-idx2; i++) {
		middle += str1[i];
	}
	return start + middle + end;
}

// from easings.net
function easeInOutQuint(x) {
	return x < 0.5 ? 16 * x * x * x * x * x : 1 - Math.pow(-2 * x + 2, 5) / 2;
}
